```javascript
const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const alphabet = data[2] || '';
const message = data[3] || '';

const allowed = new Set(alphabet);

let possible = true;
for (const ch of message) {
    if (!allowed.has(ch)) {
        possible = false;
        break;
    }
}

console.log(possible ? 'S' : 'N');
